-- A generated document is always a PDF with no uploader and no original filename.
ALTER TABLE "documents"."stored_documents"
	ADD CONSTRAINT "stored_documents_generated_shape_check" CHECK (
		"source" <> 'generated'
		OR ("uploaded_by" IS NULL AND "original_filename" IS NULL AND "content_type" = 'application/pdf')
	);
--> statement-breakpoint
ALTER TABLE "documents"."stored_documents"
