-- A purchase order only ever arrives from the customer. The system never generates one.
ALTER TABLE "documents"."stored_documents"
	ADD CONSTRAINT "stored_documents_purchase_order_is_received_check" CHECK ("kind" <> 'purchase_order' OR "source" = 'received');
